import {toast} from "react-toastify";
import {getApiErrorMessage} from "../../api/errors";
import React, {useEffect, useRef, useState} from "react";
import {Button, LinearProgress, MenuItem, TextField} from "@mui/material";
import {useTheme} from "@mui/material/styles";
import DownloadIcon from "@mui/icons-material/Download";
import {pieArcLabelClasses, PieChart} from "@mui/x-charts/PieChart";
import {BarChart} from "@mui/x-charts/BarChart";
import {LineChart} from "@mui/x-charts";
import styledCom from "styled-components";
import {
    EmptyState,
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    Surface,
} from "../../ui/commonStyled/commonStyled";
import CoreButton from "../../ui/buttons/coreButton";
import Loader from "../../ui/loader/loader";
import {
    AnalyticsComparisonMode,
    AnalyticsParams,
    AnalyticsPeriodPreset,
} from "../../models/analytics";
import {
    useGetSalesAnalyticsQuery,
    useLazyExportSalesAnalyticsCsvQuery,
} from "./analyticsApi";
import {useTranslation} from "../../i18n";

const ReportsGrid = styledCom.div({
    display: "grid",
    gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
    gap: "16px",

    "@media (max-width: 980px)": {
        gridTemplateColumns: "1fr",
    },
});

const MetricGrid = styledCom.div({
    display: "grid",
    gridTemplateColumns: "repeat(4, minmax(0, 1fr))",
    gap: "12px",
    marginBottom: "16px",

    "@media (max-width: 1100px)": {
        gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
    },

    "@media (max-width: 640px)": {
        gridTemplateColumns: "1fr",
    },
});

const MetricBlock = styledCom(Surface)({
    display: "grid",
    gap: "6px",
});

const MetricLabel = styledCom.span({
    color: "var(--color-muted)",
    fontSize: "12px",
    fontWeight: 760,
});

const MetricValue = styledCom.strong({
    color: "var(--color-text)",
    fontSize: "clamp(22px, 2.4vw, 30px)",
    fontWeight: 800,
    letterSpacing: "-.04em",
    fontVariantNumeric: "tabular-nums",
});

const ChartBlock = styledCom(Surface)({
    display: "grid",
    gap: "12px",
    minWidth: 0,
    overflow: "hidden",
});

const ChartTitle = styledCom.h2({
    margin: 0,
    color: "var(--color-text)",
    fontSize: "17px",
    fontWeight: 780,
    letterSpacing: 0,
});

const Actions = styledCom.div({
    display: "flex",
    gap: "10px",
    alignItems: "center",
    flexWrap: "wrap",
});

const formatCurrency = (value: number, locale: string) =>
    new Intl.NumberFormat(locale, {
        maximumFractionDigits: 2,
        minimumFractionDigits: 0,
    }).format(value);

const downloadBlob = (blob: Blob, filename: string) => {
    const href = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = href;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(href);
};

const Reports = () => {
    const theme = useTheme();
    const {locale, t} = useTranslation();
    const [period, setPeriod] = useState(AnalyticsPeriodPreset.CurrentMonth);
    const analyticsParams: AnalyticsParams = {
        period,
        comparisonMode: AnalyticsComparisonMode.PreviousEquivalentPeriod,
        timeZoneId: Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC",
        operationsPageNumber: 1,
        operationsPageSize: 10,
    };
    const {data: analytics, isLoading, isError, isFetching, refetch} = useGetSalesAnalyticsQuery(analyticsParams);
    const [exportCsv, {isFetching: isExporting}] = useLazyExportSalesAnalyticsCsvQuery();
    const chartContainer = useRef<HTMLElement>(null);
    const [chartWidth, setChartWidth] = useState(360);
    useEffect(() => {
        const element = chartContainer.current;
        if (!element) return;
        const measure = () => {
            const width = element.getBoundingClientRect().width;
            if (!width) return;
            const style = window.getComputedStyle(element);
            setChartWidth(Math.max(220, Math.floor(width - parseFloat(style.paddingLeft) - parseFloat(style.paddingRight) - 2)));
        };
        measure();
        const observer = typeof ResizeObserver === "undefined" ? undefined : new ResizeObserver(measure);
        observer?.observe(element);
        window.addEventListener("resize", measure);
        return () => {observer?.disconnect(); window.removeEventListener("resize", measure);};
    }, [analytics]);

    const handleExport = async () => {
        try {
            const csvBlob = await exportCsv(analyticsParams).unwrap();
            downloadBlob(csvBlob, "sales-analytics.csv");
            toast.success(t("Отчёт сохранён в загрузки."));
        } catch (failure) {
            const message = getApiErrorMessage(failure, t("Не удалось загрузить данные. Повторите запрос."));
            toast.error(message, {toastId: `query-error:${message}`});
        }
    };

    if (isLoading) {
        return <Loader/>;
    }

    if (isError || !analytics) {
        return (
            <MainDiv>
                <EmptyState>
                    <strong>{t("Аналитика не загружена")}</strong>
                    <span>Не удалось получить отчёт. Повторите загрузку.</span>
                    <Button onClick={() => void refetch()}>Повторить загрузку отчёта</Button>
                </EmptyState>
            </MainDiv>
        );
    }

    const timeSeriesLabels = analytics.timeSeries.map((point) => point.label);
    const timeSeriesRevenue = analytics.timeSeries.map((point) => point.netRevenue);
    const itemRankingLabels = analytics.itemRankings.slice(0, 6).map((item) => item.name);
    const itemRankingRevenue = analytics.itemRankings.slice(0, 6).map((item) => item.netRevenue);
    const breakdownData = analytics.sourceBreakdown.map((item) => ({
        id: item.key,
        value: item.netRevenue,
        label: item.name,
    }));

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{t("Отчеты")}</PageTitle>
                    <PageSubtitle>
                        {t("Выручка, заказы, популярные позиции и источники продаж.")}
                    </PageSubtitle>
                </PageTitleGroup>
                <Actions>
                    <TextField select size="small" label="Период отчёта" value={period} disabled={isFetching} onChange={event => setPeriod(Number(event.target.value))} sx={{minWidth: 190}}>
                        {[[AnalyticsPeriodPreset.Today, "Сегодня"], [AnalyticsPeriodPreset.Yesterday, "Вчера"], [AnalyticsPeriodPreset.CurrentWeek, "Текущая неделя"], [AnalyticsPeriodPreset.CurrentMonth, "Текущий месяц"], [AnalyticsPeriodPreset.PreviousMonth, "Прошлый месяц"], [AnalyticsPeriodPreset.Last30Days, "Последние 30 дней"], [AnalyticsPeriodPreset.CurrentYear, "Текущий год"]].map(([value, label]) => <MenuItem key={value} value={value}>{label}</MenuItem>)}
                    </TextField>
                    <CoreButton
                        muiType="info"
                        leftIcon={<DownloadIcon/>}
                        disabled={isExporting || isFetching}
                        text={isExporting ? t("Экспорт...") : t("Экспорт CSV")}
                        onClick={handleExport}
                    />
                </Actions>
            </PageHeader>
            {isFetching && <LinearProgress aria-label="Обновление отчёта" sx={{mb: 2}}/>}

            <MetricGrid>
                <MetricBlock>
                    <MetricLabel>{t("Валовая выручка")}</MetricLabel>
                    <MetricValue>{formatCurrency(analytics.summary.grossRevenue, locale)} BYN</MetricValue>
                </MetricBlock>
                <MetricBlock>
                    <MetricLabel>{t("Чистая выручка")}</MetricLabel>
                    <MetricValue>{formatCurrency(analytics.summary.netRevenue, locale)} BYN</MetricValue>
                </MetricBlock>
                <MetricBlock>
                    <MetricLabel>{t("Заказы")}</MetricLabel>
                    <MetricValue>{analytics.summary.orderCount}</MetricValue>
                </MetricBlock>
                <MetricBlock>
                    <MetricLabel>{t("Средний чек")}</MetricLabel>
                    <MetricValue>{formatCurrency(analytics.summary.averageCheck, locale)} BYN</MetricValue>
                </MetricBlock>
            </MetricGrid>

            <ReportsGrid>
                <ChartBlock ref={chartContainer}>
                    <ChartTitle>{t("Тренд чистой выручки")}</ChartTitle>
                    {timeSeriesLabels.length === 0 ? (
                        <EmptyState><span>{t("Нет данных")}</span></EmptyState>
                    ) : <LineChart
                        xAxis={[{scaleType: "point", data: timeSeriesLabels}]}
                        series={[{data: timeSeriesRevenue, area: true}]}
                        colors={[theme.palette.primary.main]}
                        width={chartWidth}
                        height={300}
                    />}
                </ChartBlock>
                <ChartBlock>
                    <ChartTitle>{t("Топ позиций")}</ChartTitle>
                    {itemRankingLabels.length === 0 ? (
                        <EmptyState><span>{t("Нет данных")}</span></EmptyState>
                    ) : <BarChart
                        xAxis={[{scaleType: "band", data: itemRankingLabels}]}
                        series={[{data: itemRankingRevenue}]}
                        colors={[theme.palette.primary.main]}
                        width={chartWidth}
                        height={300}
                    />}
                </ChartBlock>
                <ChartBlock>
                    <ChartTitle>{t("Тренд количества заказов")}</ChartTitle>
                    {timeSeriesLabels.length === 0 ? (
                        <EmptyState><span>{t("Нет данных")}</span></EmptyState>
                    ) : <LineChart
                        xAxis={[{scaleType: "point", data: timeSeriesLabels}]}
                        series={[{data: analytics.timeSeries.map((point) => point.orderCount)}]}
                        yAxis={[{min: 0, tickMinStep: 1}]}
                        colors={[theme.palette.primary.main]}
                        width={chartWidth}
                        height={300}
                    />}
                </ChartBlock>
                <ChartBlock>
                    <ChartTitle>{t("Выручка по источникам")}</ChartTitle>
                    {breakdownData.length === 0 ? (
                        <EmptyState><span>{t("Нет данных по источникам")}</span></EmptyState>
                    ) : <PieChart
                        series={[
                            {
                                arcLabel: (item) => `${item.label} (${formatCurrency(Number(item.value), locale)})`,
                                arcLabelMinAngle: 45,
                                data: breakdownData,
                            },
                        ]}
                        sx={{
                            [`& .${pieArcLabelClasses.root}`]: {
                                fill: theme.palette.primary.contrastText,
                                fontWeight: "bold",
                            },
                        }}
                        colors={[theme.palette.primary.main, theme.palette.success.main, theme.palette.warning.main, theme.palette.error.main]}
                        width={chartWidth}
                        height={300}
                    />}
                </ChartBlock>
            </ReportsGrid>
        </MainDiv>
    );
};

export default Reports;
