import {OrderItemType} from "./order";

export enum AnalyticsPeriodPreset {
    Custom = 0,
    Today = 1,
    Yesterday = 2,
    CurrentWeek = 3,
    PreviousWeek = 4,
    CurrentMonth = 5,
    PreviousMonth = 6,
    CurrentQuarter = 7,
    PreviousQuarter = 8,
    CurrentYear = 9,
    PreviousYear = 10,
    Last7Days = 11,
    Last30Days = 12,
    Last90Days = 13,
    Last12Months = 14,
}

export enum AnalyticsGroupBy {
    Hour = 0,
    Day = 1,
    Week = 2,
    Month = 3,
    Quarter = 4,
    Year = 5,
}

export enum AnalyticsComparisonMode {
    None = 0,
    PreviousEquivalentPeriod = 1,
    PreviousWeek = 2,
    PreviousMonth = 3,
    PreviousQuarter = 4,
    PreviousYear = 5,
    Custom = 6,
    Plan = 7,
    Budget = 8,
    TargetKpi = 9,
}

export enum AnalyticsTrendDirection {
    None = 0,
    Up = 1,
    Down = 2,
    Flat = 3,
}

export enum AnalyticsMetricImpact {
    Neutral = 0,
    Positive = 1,
    Negative = 2,
    Warning = 3,
    Unknown = 4,
}

export enum AnalyticsDataQualitySeverity {
    Info = 0,
    Warning = 1,
    Critical = 2,
}

export interface AnalyticsParams {
    period?: AnalyticsPeriodPreset;
    from?: string;
    to?: string;
    timeZoneId?: string;
    groupBy?: AnalyticsGroupBy;
    comparisonMode?: AnalyticsComparisonMode;
    compareFrom?: string;
    compareTo?: string;
    orderStatuses?: string;
    searchTerm?: string;
    customerId?: number;
    sourceId?: number;
    paymentMethodId?: number;
    deliveryMethodId?: number;
    categoryId?: number;
    itemType?: OrderItemType;
    productId?: number;
    serviceId?: number;
    operationsPageNumber?: number;
    operationsPageSize?: number;
}

export interface AnalyticsPeriod {
    fromUtc: string;
    toUtc: string;
    fromLocal: string;
    toLocal: string;
    timeZoneId: string;
    preset: AnalyticsPeriodPreset;
    groupBy: AnalyticsGroupBy;
    comparisonMode: AnalyticsComparisonMode;
}

export interface AnalyticsFilter {
    searchTerm?: string | null;
    orderStatuses: string[];
    customerId?: number | null;
    sourceId?: number | null;
    paymentMethodId?: number | null;
    deliveryMethodId?: number | null;
    categoryId?: number | null;
    itemType?: OrderItemType | null;
    productId?: number | null;
    serviceId?: number | null;
}

export interface AnalyticsSummary {
    orderCount: number;
    grossRevenue: number;
    netRevenue: number;
    revenueBeforeDiscounts: number;
    discountAmount: number;
    discountRatePercent: number;
    productRevenue: number;
    serviceRevenue: number;
    deliveryRevenue: number;
    averageCheck: number;
    itemQuantity: number;
    productLineCount: number;
    serviceLineCount: number;
}

export interface AnalyticsMetric {
    key: string;
    name: string;
    value?: number | null;
    comparisonValue?: number | null;
    delta?: number | null;
    deltaPercent?: number | null;
    direction: AnalyticsTrendDirection;
    impact: AnalyticsMetricImpact;
    isAvailable: boolean;
    unavailableReason?: string | null;
}

export interface AnalyticsTimeSeriesPoint {
    fromUtc: string;
    toUtc: string;
    fromLocal: string;
    toLocal: string;
    label: string;
    orderCount: number;
    grossRevenue: number;
    netRevenue: number;
    discountAmount: number;
    averageCheck: number;
}

export interface AnalyticsBreakdown {
    key: string;
    name: string;
    orderCount: number;
    grossRevenue: number;
    netRevenue: number;
    sharePercent: number;
}

export interface AnalyticsItemRanking {
    key: string;
    itemType: OrderItemType;
    productId?: number | null;
    serviceId?: number | null;
    name: string;
    categoryId?: number | null;
    categoryName: string;
    orderCount: number;
    quantity: number;
    grossRevenue: number;
    netRevenue: number;
    averageUnitPrice: number;
    sharePercent: number;
    marginStatus: string;
}

export interface AnalyticsCustomerRanking {
    customerId: number;
    name: string;
    phone: string;
    orderCount: number;
    grossRevenue: number;
    netRevenue: number;
    averageCheck: number;
    sharePercent: number;
    lastOrderDate?: string | null;
    debtStatus: string;
}

export interface AnalyticsOperationsPage {
    pageNumber: number;
    pageSize: number;
    totalCount: number;
    totalPages: number;
    items: AnalyticsOperation[];
}

export interface AnalyticsOperation {
    orderId: number;
    createdDate: string;
    status: string;
    customerId: number;
    customerName: string;
    source: string;
    paymentMethod: string;
    deliveryMethod: string;
    totalSum: number;
    finalSum: number;
    discountAmount: number;
    itemLineCount: number;
    mainItemName: string;
}

export interface AnalyticsDataQualityIssue {
    severity: AnalyticsDataQualitySeverity;
    code: string;
    message: string;
    affectedCount: number;
}

export interface AnalyticsMetricDefinition {
    metric: string;
    businessDefinition: string;
    formula: string;
    sourceEntities: string;
    dateField: string;
    includedStatuses: string;
    excludedStatuses: string;
    currencyRules: string;
    taxRules: string;
    returnRules: string;
    permissionRequirements: string;
    knownLimitations: string;
    isAvailable: boolean;
}

export interface SalesAnalytics {
    period: AnalyticsPeriod;
    comparisonPeriod?: AnalyticsPeriod | null;
    filters: AnalyticsFilter;
    summary: AnalyticsSummary;
    comparisonSummary?: AnalyticsSummary | null;
    metrics: AnalyticsMetric[];
    timeSeries: AnalyticsTimeSeriesPoint[];
    itemRankings: AnalyticsItemRanking[];
    customerRankings: AnalyticsCustomerRanking[];
    statusBreakdown: AnalyticsBreakdown[];
    sourceBreakdown: AnalyticsBreakdown[];
    paymentMethodBreakdown: AnalyticsBreakdown[];
    deliveryMethodBreakdown: AnalyticsBreakdown[];
    operations: AnalyticsOperationsPage;
    dataQualityIssues: AnalyticsDataQualityIssue[];
    metricDefinitions: AnalyticsMetricDefinition[];
    requiredModelExtensions: string[];
}
